#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_resize_realloc_failure(void) {
    // Setup: create a valid buffer (2 allocations: struct + data)
    buffer_t *buf = buffer_new_with_size(10);
    TEST_ASSERT_NOT_NULL(buf);

    // Fill buffer with known data
    memcpy(buf->data, "abc", 4); // includes null terminator

    // Prepare to fail the next allocation (realloc inside buffer_resize)
    // 2 allocations already done in setup, so fail after 2
    malloc_fail_after(2);

    // Attempt to resize buffer to a larger size (e.g., 2000)
    int ret = buffer_resize(buf, 2000);

    // Assert: buffer_resize returns -1 on allocation failure
    TEST_ASSERT_EQUAL_INT(-1, ret);

    // Assert: buffer contents and allocation remain unchanged
    helper_assert_buffer_data_equals(buf, "abc");
    helper_assert_buffer_length(buf, 3);
    helper_assert_buffer_size(buf, 10);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_resize_realloc_failure);
    return UNITY_END();
}

